import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>从网上下载的 WebP 图片，常常在你需要的软件里打不开。转成 JPG 不到一分钟就能搞定，转出来的文件到处都能用。</p>\n<p>唯一有点讲究的是透明度。JPG 存不了透明像素，转换前要先给透明区域选一个填充色。</p>\n<p>这篇指南一步一步带你走完整个流程，让你第一次转换就出干净的结果。</p>\n<h2 id=\"before-you-start\">开始之前：先检查有没有透明部分</h2>\n<p>打开 WebP 看一眼背景。照片没有透明部分，可以直接转换，不用管填充色。</p>\n<p>标志、贴纸或者抠出来的产品图很可能带有透明区域。透明部分需要一个填充色，开始之前最好先想好用哪个。</p>\n<p>白色适合大多数场景。文档、网页和表单的底色通常是白色，白色填充看起来最自然。</p>\n<p>单个文件最大支持 25MB，高清下载图和大尺寸截图都不用提前处理，直接就能转。</p>\n<h2 id=\"step-1-open-tool\">第 1 步：打开 WebP 转 JPG 工具</h2>\n<p>在浏览器里打开 <a href=\"/zh/webp-zhuan-jpg/\">WebP 转 JPG 工具</a>。Windows、Mac、Linux、ChromeOS、安卓和 iOS 都能用，不用安装任何东西。</p>\n<p>页面上有上传区、填充色选择器和画质滑块这三个控件，整个操作就是它们了。</p>\n<p>不用注册账号，文件也不会上传。转换就在你的设备上完成，私人图片和下载文件也不用担心外泄。</p>\n<p>用手机的话，直接在手机浏览器里打开这个页面就行。点一下上传区，就能从下载文件夹或相册里选 WebP 文件。</p>\n<h2 id=\"step-2-upload\">第 2 步：上传 WebP 文件</h2>\n<p>把 WebP 文件拖到上传区，或者点一下打开文件选择器。一次选多个文件，就能批量转换。</p>\n<p>每个文件都会显示为一张卡片，带有缩略图、尺寸和文件大小。快速扫一眼，就能确认传对了文件，没有多余的混进来。</p>\n<p>有些网站保存图片时不带文件后缀。这些文件照样能转，因为工具是按文件实际内容来识别的，不看文件名。</p>\n<p>电脑上还能用 Ctrl+V 直接粘贴剪贴板里的图片。WebP 图片在别的软件里复制好之后，这个办法很方便。</p>\n<h2 id=\"step-3-matte-colour\">第 3 步：选填充色</h2>\n<p>点填充色选择器，给透明区域选一个填充颜色。默认白色，适合大多数用途。</p>\n<p>深色设计就选黑色，或者直接输入十六进制颜色码，精确匹配某个网站的背景色。背景对上了，标志看起来就像本来长在那里一样。</p>\n<p>如果你的 WebP 没有透明部分，这个设置不起任何作用。照片不管选什么颜色，都会原样通过。</p>\n<p>标志要放在纯白背景上时，白色填充就是正确选择。转出来的 JPG 干净利落，放在白底页面上很自然。</p>\n<h2 id=\"step-4-quality\">第 4 步：设置画质滑块</h2>\n<p>画质滑块决定 JPG 编码器保留多少细节。对大多数图片来说，85% 是最佳平衡点。</p>\n<p>要拿去打印的图片，用 90% 或更高的画质。打印会放大屏幕上看不出的瑕疵，单张重要图片多占一点空间完全值得。</p>\n<p>带文字的截图同样要保持 85% 以上。小字在低画质下会糊掉，模糊的截图看起来很不专业。</p>\n<p>只有遇到文件大小限制时，才把画质降到 80%。这一步常常能让文件小一半，肉眼却几乎看不出变化。</p>\n<h2 id=\"step-5-convert-preview\">第 5 步：转换并预览结果</h2>\n<p>点“转换”按钮。每个文件独立转换，进度可以一张卡片一张卡片地看。</p>\n<p>每张卡片都会显示转换后的 JPG 大小和原来 WebP 大小的对比。JPG 更大是正常的，因为 WebP 更高效。</p>\n<p>点卡片上的“对比”可以并排检查结果。拖动分隔线，放大看文字、边缘和填充效果。</p>\n<p>如果文字看着发软，把画质提高 5 个点再转一次。原 WebP 还留在队列里，不用重新上传。</p>\n<h2 id=\"step-6-download\">第 6 步：下载 JPG 文件</h2>\n<p>点单张卡片上的“下载”，就能保存这一张 JPG。文件名保持原名，只把后缀换成 .jpg。</p>\n<p>批量转换时，点“全部下载”可以拿到一个 ZIP，里面装着所有转好的 JPG。这比一张一张下载快得多。</p>\n<p>用之前先检查一遍下载好的文件。在看图软件里打开一张 JPG，确认显示正常，也确认它能在你需要的软件里打开。</p>\n<p>原 WebP 文件也留着。JPG 永远变不回完美的 WebP，原件就是你的保险。</p>\n<ol>\n<li>打开 WebP 转 JPG 工具，上传 WebP 文件。</li>\n<li>给透明区域选一个填充色。</li>\n<li>把画质滑块设到 85%。</li>\n<li>转换后用对比功能预览，再下载 JPG。</li>\n</ol>\n<h2 id=\"converting-a-batch\">批量转换下载的图片</h2>\n<p>在文件选择器里一次选中多个 WebP 文件。它们会全部进入队列，点一下就能全部转成 JPG。</p>\n<p>整批用同一个填充色和画质。同一份文档或同一个项目里的图片，保持一致才专业。</p>\n<p>批量运行时留意错误提示。某个损坏的文件只会显示警告，不会拖垮整批，其他好文件照常完成。</p>\n<p>批量下载的 ZIP 解压到一个新文件夹里。转好的 JPG 和原 WebP 混在一个文件夹里，以后很容易搞混。</p>\n<h2 id=\"white-background-trick\">做出纯白背景的小技巧</h2>\n<p>标志需要纯白背景时，把填充色设为纯白，十六进制颜色码是 ffffff。这样所有透明区域都会填上干净的白色。</p>\n<p>在白底页面上对照检查一下结果。标志应该和背景融为一体，看不出原来透明区域的边缘。</p>\n<p>如果标志带有柔和的阴影，阴影会直接压在白色上。这是正常的，因为 JPG 存不了半透明，出来的结果依然干净。</p>\n<p>如果标志要在很多种背景上使用，那就别转 JPG。留着 WebP 或 PNG，透明度才能保留下来。</p>\n<h2 id=\"fixing-problems\">常见问题怎么修</h2>\n<p>透明贴纸转出来带个黑框，说明填充色是黑色或者没设置。改成白色或你的页面颜色，再转一次就行。</p>\n<p>文字看着模糊，是画质太低了。把滑块拉到 90%，用原 WebP 再转一次。</p>\n<p>某个文件转失败了，先确认它是不是真正的 WebP。没有后缀的文件可能是伪装成别的格式的 JPG 或 PNG，工具是按内容来判断的。</p>\n<p>动态 WebP 转出来变成静态图，这是正常的。转换器只取第一帧，因为 JPG 存不了动画。</p>\n<h2 id=\"mobile-tips\">手机和平板上的小技巧</h2>\n<p>手机上点一下上传区，从下载文件夹或相册里选 WebP 文件。转换就在手机上完成，JPG 会下载到你的设备里。</p>\n<p>手机上批量别贪多，大文件在手机处理器上解码比较慢。一次转十张左右比较舒服。</p>\n<p>下载的文件在手机的“下载”文件夹里。iPhone 在“文件”应用里找，安卓在文件管理器里找。</p>\n<p>要转一大批下载图，还是用电脑。更快的处理器和更大的屏幕，处理很多文件要轻松得多。</p>\n<h2 id=\"converting-wallpapers\">转换下载的壁纸</h2>\n<p>网上下载的壁纸常常是 WebP 文件，在老系统上做桌面背景之前要先转换。JPG 壁纸到处都能用。</p>\n<p>壁纸用 90% 画质转成 JPG。图片铺满屏幕，颜色依然饱满，在任何操作系统上都能设为背景。</p>\n<p>转换前先看尺寸。壁纸最好和屏幕分辨率匹配，小图拉大到铺满大屏幕，再怎么转都会糊。</p>\n<p>手机壁纸就按手机屏幕尺寸来转。1080×1920 的 JPG 在大多数手机上都很清晰，文件也不大，设置起来很快。</p>\n<p>如果这张壁纸很重要，留着 WebP 原件。它是画质最好的版本，换了不同屏幕尺寸的设备还能再转。</p>\n<h2 id=\"webp-school-project\">为学校作业转换 WebP</h2>\n<p>学校作业经常要用到网上的图片，而这些图片通常是 WebP。学校电脑上的老软件可能显示不了，所以先转成 JPG 更稳妥。</p>\n<p>放进作业之前，先把图片用 85% 画质转成 JPG。JPG 在 PowerPoint、Word 和 Google 幻灯片里都能干净嵌入，作业在任何一台学校电脑上打开都正常。</p>\n<p>图片多的作业，整批一起转。批量转换几分钟就能完成，转好的 JPG 直接拖进幻灯片就行。</p>\n<p>转换后检查一遍图片。快速看一下每一张，确认都能正常显示，展示那天就不会出现坏图。</p>\n<p>记得在作业里注明图片来源。转过格式的图片依然属于原作者，规范的引用是良好的学术习惯。</p>\n<h2 id=\"webp-for-cv\">为简历转换 WebP</h2>\n<p>简历照片必须在招聘方电脑上打得开，WebP 照片可能直接失败。放进简历之前先转成 JPG，再仔细检查一遍结果。</p>\n<p>用正式的证件照，别用随手拍的生活照。照片要清晰露出面部，背景干净，光线好，表情自然。</p>\n<p>照片用 90% 画质转成 JPG。人脸保持清晰，颜色自然，在招聘方眼里显得很专业。</p>\n<p>转换后看一下文件大小。简历里塞一张 4MB 的照片，整份文件可能超出招聘网站的上传上限，太大了就先压缩一下。</p>\n<p>加好照片后把简历存成 PDF。PDF 在任何设备上版式都不会乱，Word 文档换台电脑打开可能会自己重排。</p>\n<h2 id=\"webp-for-printer\">为打印转换 WebP</h2>\n<p>打印机只认 JPG 或 PNG，把 WebP 发给打印店可能直接被系统拒绝。先转成 JPG，再确认一下打印店的具体要求。</p>\n<p>打印用的图片，画质保持在 90% 以上。6 寸照片需要每一个像素的细节，低画质 JPG 的瑕疵印在纸上会很明显。</p>\n<p>打印前先看尺寸。800 像素宽的图片印 3 寸很清晰，印 10 寸就糊了，打印尺寸要和像素数匹配。</p>\n<p>要印大幅的，就用手头分辨率最高的原图。网上下载的 WebP 通常比较小，再怎么转换也变不出大幅打印需要的像素。</p>\n<p>重要的照片先印一张小样试试。一张小样就能确认颜色和清晰度，再决定要不要下大单。</p>\n<h2 id=\"webp-received-by-email\">转换邮件里收到的 WebP</h2>\n<p>图片有时会以 WebP 附件的形式发到邮箱，在收件人的看图软件里打不开。转成 JPG 马上就能解决问题。</p>\n<p>先把附件保存到设备上，再拖进转换器。直接从邮件应用里转换基本行不通，因为文件必须先存在你的设备上。</p>\n<p>保存后检查一下画质。邮件服务有时会压缩附件，保存下来的文件可能已经比原图画质低了。</p>\n<p>转换完如果别人也需要，就把 JPG 附在回复里发回去。JPG 在邮件里的每个人那儿都能打开，原来的 WebP 有一半人打不开。</p>\n<p>原附件留在邮箱里当备份。万一转换出了问题，还能重新下载再试不同的设置，不用麻烦发件人重发一遍。</p>\n<h2 id=\"webp-for-family-album\">为家庭相册转换 WebP</h2>\n<p>家庭相册的照片要让每台设备都打得开，WebP 在长辈的旧手机上可能失败。先把整本相册转成 JPG，所有人看到的都是一样的照片。</p>\n<p>整本相册一次批量转换，画质用 85%。照片看着干净，文件到处能打开，相册马上就能分享给全家人。</p>\n<p>先整理照片，删掉模糊的和重复的。三百张的家庭相册往往只有五十张值得留，只转这些能省下不少时间。</p>\n<p>通过共享相册或云链接分享 JPG。不管设备新旧，所有人看到的都是同一套照片，谁都不用另外装东西。</p>\n<p>分享完把 WebP 原件存进归档文件夹。它们是画质最好的版本，以后哪个亲戚需要别的格式，还能再转。</p>\n<p>整个流程就是：上传、选填充色、设画质、下载。想了解背后的原理，可以看<a href=\"/zh/blog/webp-zhuan-jpg-wanquan-zhinan/\">WebP 转 JPG 完全指南</a>；兼容性问题可以看<a href=\"/zh/blog/webp-zhuan-jpg-jianrongxing/\">WebP 转 JPG：兼容性比压缩更重要的时候</a>。如果要保留透明度，<a href=\"/zh/webp-zhuan-png/\">WebP 转 PNG 工具</a>更合适。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"怎么让转换后的标志后面是纯白背景？","answer":"转换前把填充色设为纯白，十六进制颜色码是 ffffff。这样所有透明区域都会填上干净的白色，标志放在白底页面上能融为一体。使用前先在白色背景上对照检查一下，因为柔和的阴影在转换时会直接压在白色上。"},{"question":"没有文件后缀的 WebP 文件能转换吗？","answer":"可以。有些网站保存图片时不带后缀，但工具是按文件实际内容来识别的，不看文件名。直接把文件拖进去，解码器会认出它是 WebP。就算它其实是伪装的 JPG 或 PNG，工具也能处理。"},{"question":"WebP 截图应该用什么画质设置？","answer":"85% 或更高最适合截图，因为小字在低画质下糊得很快。照片用 85% 也是最佳平衡点，大小和画质兼顾。只有遇到文件大小限制时，才降到 80%。"},{"question":"能一次把很多下载的 WebP 转成 JPG 吗？","answer":"可以。在文件选择器里一次选中多个 WebP 文件，点一下就能全部转换。每个文件独立转换，整批可以打包成一个 ZIP 一次下载。整批用同一个填充色和画质，结果才一致。"},{"question":"转换后的 JPG 能在 Word 和 PowerPoint 里打开吗？","answer":"可以。JPG 是 Word、PowerPoint、Photoshop 和其他所有办公与设计软件原生支持的格式。转换后的 JPG 是标准文件，没有任何特殊要求，打开和打印都和相机直出的 JPG 一模一样。"},{"question":"WebP 转 JPG 能离线转换吗？","answer":"页面加载完成后，转换就在浏览器本地运行，不需要联网。只有第一次打开页面时需要网络。之后只要不关闭标签页，就可以离线一直转换 WebP 文件。"}];
